-- 最简版本的 角色驱动, 仅供 2023春节活动;  没有跑停功能

---@class HumanSimpleController
---@field playerInputBehaviour      Engine.Modules.LuaBehaviour -- PlayerInput
---@field animator                  UnityEngine.Animator
---@field rigid                     UnityEngine.Rigidbody
local HumanSimpleController = Class('HumanSimpleController')

-- ========================================================

local Mathf = CS.UnityEngine.Mathf
local Time = CS.UnityEngine.Time
local Vector3 = CS.UnityEngine.Vector3
local Quaternion = CS.UnityEngine.Quaternion
local AnimatorStateInfo = CS.UnityEngine.AnimatorStateInfo
local Animator = CS.UnityEngine.Animator

local UIModule = CS.Engine.UI.UIModule
local SDKService = import('Game.Entry.SDKService')
local KTool = CS.Engine.Lib.KTool
local cs_coroutine = require 'XLua.cs_coroutine'

local BehaviourAction = CS.Engine.Lib.BehaviourAction

-- local PlayerInput = import('Game.Behaviours.PlayerInput')

-- ========================================================



local runMoveSpeed = 3.5  -- float, 跑步物理位移速度, 动画设计值为: 4.5
local maxAcceleration = 50.0 -- 单帧位移最大加速度
local gravity = -20.0
local maxGroundAngle = 5.0 --  地面倾角; 值越小, 越平的表面才会被判定为地面




local idleAnimationDatas = {
    { weight = 1.0, time = 2.0 }, -- [1] 演绎型idle, {idle01, idle02} 任选一
    { weight = 0.0, time = 5.0 }, -- [2] 
    { weight = 2.0, time = 2.0 }, -- [3] 演绎型idle, {idle01, idle02} 任选一
    { weight = 0.0, time = 5.0 }  -- [4]
}


-- ========================================================

function HumanSimpleController:__init()
    printInfo("   ~~~~~~~ HumanSimpleController:__init() ~~~~~~~")
    self.controller = nil
    
    self.steepNormal = Vector3.zero -- Vector3, 墙面法线集合
    self.dampMoveVec = Vector3.zero -- damp 过的值
    self.steepContactCount = 0 -- 本帧 接触的 steep surface 的数量;
    self.minGroundDotProduct = 0.0 
    self.isHitSteep = false -- 是否撞到了 steep 面, 此时需要沿着 steep 面朝侧向滑动
    self.sustainedForward = 0.0 -- 特殊的运动速度, 在玩家有效输入值 的基础上, 做了一定调整
    self.moveSpeed = 0.0 -- float 本帧物理位移速度
    self.m_transform = nil 
    self.isRunning = false -- 只有当玩家输入有效输入时, 此值才会被更新, 否则将维持之前的值

    ---:
    self.idxForIdleAnimationDatas = 1 -- 用来遍历 self.idleAnimationDatas 的 idx
    self.idleTimer = 0.0

    self.idleTagTimer = 0.0
    
    self.isLastFrameIdleTag = false

 
    -- id:
    self._Forward2      = Animator.StringToHash("Forward2")
    self._IsPlayerInput = Animator.StringToHash("IsPlayerInput")
    self._IsRunning     = Animator.StringToHash("IsRunning")
    self._IdleWeight    = Animator.StringToHash("IdleWeight")
    self._DumpInput     = Animator.StringToHash("DumpInput")

end


function HumanSimpleController:__delete()
    --printInfo("   ~~~~~~~ HumanSimpleController:__delete() ~~~~~~~")
    if not isNull(self._behaviourAction) then
        self._behaviourAction.FixedUpdateAction = nil
        self._behaviourAction.OnCollisionEnterAction = nil
        self._behaviourAction.OnCollisionStayAction = nil
    end
end




function HumanSimpleController:Awake()
    KTool.SetActive(self.controller.gameObject, true);
    --printInfo("   ~~~~~~~ HumanSimpleController:Awake() ~~~~~~~")
end



--- Init
--- 如果不挂lua Behaviour 直接调此方法初始化
---@param role UnityEngine.GameObject
---@param playerInput PlayerInput
function HumanSimpleController:Init(role, playerInput)
    --printInfo( "role name = " .. role.name )
    self.animator    = role:GetComponentInChildren(typeof(CS.UnityEngine.Animator))
    self.rigid       = role:GetComponentInChildren(typeof(CS.UnityEngine.Rigidbody))
    self.playerInput = playerInput

    local behaviourAction = KTool.GetOrAddComponent(role.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.FixedUpdateAction = function(behaviourAction)
            self:FixedUpdate()
        end

        behaviourAction.OnCollisionEnterAction = Bind(self, self.OnCollisionEnter)
        behaviourAction.OnCollisionStayAction  = Bind(self, self.OnCollisionStay)
    end
    self._behaviourAction = behaviourAction

    self.rigid.useGravity  = false
    self.rigid.isKinematic = false

    self.minGroundDotProduct = Mathf.Cos(maxGroundAngle * Mathf.Deg2Rad)
    self.m_transform = role.transform

    self.baseLayerIndex = self.animator:GetLayerIndex("Base Layer")
    self.eyeLayerIndex = self.animator:GetLayerIndex("Eye")

    self.lastEyeLayerWeight = 1.0
    self.currentEyeLayerWeight = 1.0

    -- 玩家输入时, 此值瞬变为 1.0, 玩家停止输入时, 此值缓慢过度到 0.0
    -- 当此值 小于 0.3 时, 开启 调查官 lookat 功能 (即: 只有当玩家进入 idle 状态一段时间后, 才开启)
    self.delayIdleWeight = 0.0 

    -- 玩家输入后瞬间为 1.0, 玩家停止输入后缓缓降为 0.0
    self._dumpInputVal = 0.0
end




function HumanSimpleController:Update()
    --print("   ~~~~~~~ HumanSimpleController:Update() ~~~~~~~")

    

    -- 玩家存在有效输入时,此值需要尽快响应, 
    -- 玩家停止输入后, 此值需要平滑地过渡到 0值;
    if self.playerInput.isPlayerInput then 
        self.sustainedForward = Mathf.Lerp( self.sustainedForward, self.playerInput.playerInputMoveVec.magnitude, 0.75 ) -- 0.95
        self._dumpInputVal = 1.0

    else 
        self.sustainedForward = Mathf.Lerp( self.sustainedForward, 0.0, 0.11 ) -- 缓缓降低, 争取比 _dumpInputVal 适当快一点
        self._dumpInputVal = Mathf.Lerp( self._dumpInputVal, 0.0, 0.1 ) -- 缓缓降低
    end

    if self.playerInput.isUseKeyboard  then
        -- --- 键盘模式下, 走路速度需要人为实现:
        self.isRunning = not self.playerInput.ctrlKeyFlag -- 按下 ctrl 表示走路
        self.sustainedForward = self.isRunning and self.sustainedForward or (self.sustainedForward * 0.2) -- 走路速度变慢

        local tgtSpeed = self.isRunning and runMoveSpeed or (runMoveSpeed * 0.3) -- float
        local moveLerpT = (self.moveSpeed < tgtSpeed) and 0.6 or 0.7 -- float 加速稍慢, 减速稍快
        self.moveSpeed = Mathf.Lerp( self.moveSpeed, tgtSpeed, moveLerpT )
    else 
        -- 只有在玩家有效输入时, 才会更新 isRunning 的值,
        if self.playerInput.isPlayerInput  then
            self.isRunning = self.sustainedForward > 0.8 -- 摇杆磋到较大时判定为跑, 此时会启动跑停
        end
        -- 摇杆模式下无需单向 走路速度, 全部依赖 PlayerInputMoveVec 即可,
        self.moveSpeed = runMoveSpeed
    end

    --printInfo( "sustainedForward = " .. tostring(self.sustainedForward) )
    -- UpdateAnim
    self.animator:SetFloat( self._Forward2,     self.sustainedForward, 0.012, Time.deltaTime ) -- 值越小, 平滑周期越短 (0.03)
    self.animator:SetBool( self._IsPlayerInput, self.playerInput.isPlayerInput ) -- 非0即1, 表示玩家本帧是否输入 (有效输入)
    self.animator:SetBool( self._IsRunning,     self.isRunning )
    self.animator:SetFloat( self._DumpInput,    self._dumpInputVal )

    self:SwitchIdleAnimation()


    --- 更新 delayIdleWeight:
    if self.playerInput.isPlayerInput == true then 
        self.delayIdleWeight = 1.0
    else 
        self.delayIdleWeight = Mathf.MoveTowards( self.delayIdleWeight, 0.0, 0.6 )
    end

end


-- 当 role 进入 idle 状态 若干帧后, 此值返回 true:
function HumanSimpleController:IsInDelayIdle()
    return self.delayIdleWeight > 0.5
end



-- 为支持 idle 动画的随机播放:
function HumanSimpleController:SwitchIdleAnimation()
    -- AnimatorStateInfo, 本帧(物理帧) 正在播放的 anim clip 信息;
    local baseAnimatorStateInfo = self.animator:GetCurrentAnimatorStateInfo( self.baseLayerIndex )
    local isIdleTag = baseAnimatorStateInfo:IsTag("Idle")

    self.currentEyeLayerWeight = isIdleTag and 1.0 or 0.0 
    --- 为了减少 SetLayerWeight() 的调用次数:
    if self.currentEyeLayerWeight ~= self.lastEyeLayerWeight then 
        self.lastEyeLayerWeight = self.currentEyeLayerWeight
        self.animator:SetLayerWeight( self.eyeLayerIndex, self.currentEyeLayerWeight )
    end

    if (self.isLastFrameIdleTag == false) and (isIdleTag == true) then -- 第一帧进入 Idle Tag 
        --printInfo("第一帧进入 Idle Tag ")
        self.idleTagTimer = 0.0
    end
    self.isLastFrameIdleTag = isIdleTag
    self.idleTagTimer = self.idleTagTimer + Time.deltaTime

    -- 进入 idle tag 的前 3 秒不播放任何 演绎型idle
    if self.idleTagTimer < 3.0 then 
        self.animator:SetFloat( self._IdleWeight, 0.0 )
        return
    end

    -- ------------------  -------------------:
    --printInfo(" -- 3秒已过: -- ")

    local animationData = idleAnimationDatas[self.idxForIdleAnimationDatas]

    self.animator:SetFloat( self._IdleWeight,   animationData.weight, 0.05, Time.deltaTime )

    self.idleTimer = self.idleTimer + Time.deltaTime
    if self.idleTimer > animationData.time then 
        self.idleTimer = 0.0 

        self.idxForIdleAnimationDatas = self.idxForIdleAnimationDatas + 1

        if self.idxForIdleAnimationDatas > #idleAnimationDatas then
            self.idxForIdleAnimationDatas = 1

            -- 重置下一回合的数据:
            idleAnimationDatas[2].time = math.random() * 4.0 + 4.0 -- 随机时间: [4.0,8.0]
            idleAnimationDatas[4].time = math.random() * 4.0 + 4.0 -- 随机时间: [4.0,8.0]
            local is01Fst = math.random() > 0.5 
            idleAnimationDatas[1].weight = is01Fst and 1.0 or 2.0
            idleAnimationDatas[3].weight = is01Fst and 2.0 or 1.0
        end

    end
end



function HumanSimpleController:FixedUpdate()
    --print("   ~~~~~~~ HumanSimpleController:FixedUpdate() ~~~~~~~")

    -- todo: 预备给潜在的脚滑问题
    -- 会导致操作响应的延迟..

    -- -- AnimatorStateInfo, 本帧(物理帧) 正在播放的 anim clip 信息;
    -- local baseAnimatorStateInfo = self.animator:GetCurrentAnimatorStateInfo( self.baseLayerIndex )
    -- local isIdleTag = baseAnimatorStateInfo:IsTag("Idle")

    -- if isIdleTag == true then 
    --     local s = Vector3.Lerp( self.rigid.velocity, Vector3.zero, 0.1 )
    --     self.rigid.velocity = s
    --     return
    -- end
    
    
    self:UpdateState()
    local velocity = self.rigid.velocity -- !!!!!!!!!!! Vector3
    -- ----- 位移: ------:
    local xAxis = self.playerInput.rightDir.normalized  -- Vector3
    local zAxis = self.playerInput.forwardDir.normalized -- Vector3
    
    local oldX = Vector3.Dot(velocity, xAxis) -- float
    local oldZ = Vector3.Dot(velocity, zAxis) -- float

    local lerpT = 0.9
    if self.playerInput.isUseKeyboard then 
        lerpT = (self.dampMoveVec.magnitude < self.playerInput.playerInputMoveVec.magnitude) and 0.8 or 0.3
    else 
        lerpT = 0.9
    end
    self.dampMoveVec = Vector3.Lerp( self.dampMoveVec, self.playerInput.playerInputMoveVec, lerpT )
    
    local newX = Vector3.Dot( self.dampMoveVec, xAxis ) * self.moveSpeed -- float
    local newZ = Vector3.Dot( self.dampMoveVec, zAxis ) * self.moveSpeed -- float

    local maxSpeedChange = maxAcceleration * Time.deltaTime -- float 

    -- 限制每帧位移最大幅度
    newX = Mathf.MoveTowards(oldX, newX, maxSpeedChange)
    newZ = Mathf.MoveTowards(oldZ, newZ, maxSpeedChange)

    local newVelocity = velocity + xAxis * (newX - oldX) + zAxis * (newZ - oldZ) -- Vector3

    if self.isHitSteep  then
        -- 如果角色朝向 steep surface 方向运动, 就要把这个方向的运动分量剪掉
        if Vector3.Dot( newVelocity.normalized, self.steepNormal ) < 0 then
            local steepNormalXZ = Vector3.ProjectOnPlane( self.steepNormal, self.playerInput.upDir ).normalized -- Vector3
            newVelocity = Vector3.ProjectOnPlane( newVelocity, steepNormalXZ ) -- 仅保留 沿着 steep 滑动的分量;
        end
    end

    velocity.x = newVelocity.x
    velocity.z = newVelocity.z

    velocity = velocity + self.playerInput.upDir * gravity * Time.deltaTime -- 此处不能改用 AddForce(), 因为它会考虑 质量mass 因素;
    
    self.rigid.velocity = velocity -- !!!!!!!!!!!
    -- 转向一定会被执行;
    self:HandleTurn()
    self:ClearState()
    -- ---------------- 人为规定: 此处是整轮 物理循环 的终点 -----------//
end




function HumanSimpleController:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    --printInfo("   ~~~~~~~ HumanSimpleController:OnDestroy() ~~~~~~~")
end



function HumanSimpleController:HandleTurn()
    local yRotateMaxSpeed = 0.32 -- float (0.25) 值越大, 转身速度越快
    local roleTgtForward = self.playerInput.tgtMoveDir -- Vector3
    local forward = Vector3.RotateTowards( self.m_transform.forward, roleTgtForward, yRotateMaxSpeed, 0.0 ).normalized -- Vector3 在玩家平面上的 xz面旋转插值;
    local up = self.playerInput.upDir -- Vector3
    self.rigid:MoveRotation( Quaternion.LookRotation( forward, up ) )
end



--- OnCollisionEnter
---@param collision UnityEngine.Collision
function HumanSimpleController:OnCollisionEnter(_, collision)
    self:EvaluateCollision(collision)
end
--- OnCollisionStay
---@param collision UnityEngine.Collision
function HumanSimpleController:OnCollisionStay(_, collision)
    self:EvaluateCollision(collision)
end
-- 一套依赖 collider 的地面探测
function HumanSimpleController:EvaluateCollision(collision)

    for i=0, collision.contactCount-1 do
    
        local normal = collision:GetContact(i).normal -- Vector3, surface normal
        local upDot = Vector3.Dot(self.playerInput.upDir, normal) -- float

        -- 坡度太陡了, 不属于 ground
        -- 但是只要这个 surface 不是朝向下方的, 那么都算是 steep surface;
        -- 暂不关心由多个 steep surface 构成的 虚拟 ground surface; (比如两个 steep surface 构成的 狭沟)
        if (upDot < self.minGroundDotProduct) and (upDot > -0.01)  then
            local steepNormal = self.steepNormal
            self.steepNormal = Vector3(steepNormal.x + normal.x, steepNormal.y + normal.y, steepNormal.z + normal.z)
            self.steepContactCount = self.steepContactCount + 1
        end
    end
end


function HumanSimpleController:UpdateState()
    self.steepNormal:Normalize() -- 零向量 归一化后 依然是 零向量;
    self.isHitSteep = self.steepContactCount > 0
end
   
		
function HumanSimpleController:ClearState()
    self.steepContactCount = 0
    self.steepNormal = Vector3.zero
end


return HumanSimpleController

